/**
 * borradorFacturaFerros.js — BORRADOR DE FACTURA con la plantilla oficial
 * de FERROSCA (FERROS COLL DE L'ALBA S.L.), 24/09/2026.
 *
 * Copiada del borrador real de Ferros que pasó Maria («Borrador de factura
 * 85.pdf»): cabecera ferrosCA (logo + datos de empresa, imagen extraída del
 * PDF), bloques GRISES (BORRADOR FACTURA / FECHA BORRADOR / C.I.F CLIENTE /
 * INFORMACIÓN CLIENTE / Nº Obra), tabla COD. ARTÍCULO / DESCRIPCIÓN /
 * CANTIDAD / UNIDAD / PRECIO / DTO / IMPORTE / IVA, forma de pago
 * «Transferencia bancaria CaixaBank ES41 2100 0019 4902 0071 3350 · SWIFT
 * CAIXESBBXXX», cuadro BASE IMPONIBLE / % / IVA / TOTAL, texto LOPD y
 * banner ferrosCA al pie. Mismas reglas que el de ALSO CASALS: «BORRADOR
 * OT» + nº de OT, cliente solo con el nombre, vencimiento a 60 días.
 * EL FORMATO NO SE CAMBIA.
 */
const CABECERA_FERROS = "data:image/png;base64,";
const BANNER_FERROS = "data:image/jpeg;base64,";

const IVA_PCT = 21;
const eurN = (v) => (Number(v) || 0).toLocaleString("es-ES", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fechaLarga = (d) => d.toLocaleDateString("es-ES", { day: "numeric", month: "long", year: "numeric" });
const escapa = (s) => (s ?? "").toString().replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
// Unidad tal como sale en el borrador de Ferros (Hora / Unidad…)
const UNIDADES = { H: "Hora", HORA: "Hora", HORAS: "Hora", HR: "Hora", UD: "Unidad", UDS: "Unidad", U: "Unidad", UN: "Unidad", UNIDAD: "Unidad", M: "Metro", ML: "Metro", KG: "Kg", L: "Litro" };
const textoUnidad = (u) => {
  const t = (u ?? "").toString().trim();
  return UNIDADES[t.toUpperCase()] || t;
};

const LOPD =
  "En compliment de la LOPD 15/1999, de 13 de setembre, els informem que les dades incorporades a la present factura formen part del fitxer CLIENTS/PROVEÏDORS titularitat de ALSO CASALS INSTAL·LACIONS SL que es manté per la gestió fiscal, comptable i administrativa de l'entitat. En qualsevol moment poden exercir els drets d'accés, rectificació, oposició i, si s'escau, cancel·lació, comunicant-ho per escrit amb indicació de les seves dades a C/BARCELONA, 74 43500, TORTOSA o mitjançant correu electrònic a xavi.also@alsocasals.com. Compleix amb tots els requisits establerts per la LOPD i amb les mesures tècniques i organitzatives per garantir la seguretat de les dades personals segons RD1720/2007.";

export function htmlBorradorFacturaFerros({ numeroOT, cliente, cifCliente, filas }) {
  const num = (numeroOT || "").toString().padStart(6, "0");
  const hoy = new Date();
  const vto = new Date(hoy.getTime() + 60 * 24 * 60 * 60 * 1000); // +60 días
  const base = filas.reduce((a, l) => a + (Number(l.importe) || 0), 0);
  const iva = (base * IVA_PCT) / 100;
  const total = base + iva;

  const filaHtml = (l) => {
    const esTexto = !l.numero && !(Number(l.importe) || 0) && !(Number(l.cantidad) || 0);
    if (esTexto) {
      return `<tr><td></td><td>${escapa(l.descripcion)}</td><td class="num"></td><td class="uni"></td><td class="num"></td><td class="num">0</td><td class="num"></td><td class="num"></td></tr>`;
    }
    return `<tr>
      <td>${escapa(l.numero)}</td>
      <td>${escapa(l.descripcion)}</td>
      <td class="num">${String(l.cantidad).replace(".", ",")}</td>
      <td class="uni">${escapa(textoUnidad(l.unidad))}</td>
      <td class="num">${eurN(l.precio)}</td>
      <td class="num">${l.dtoPct ? String(l.dtoPct).replace(".", ",") : "0"}</td>
      <td class="num">${eurN(l.importe)}</td>
      <td class="num">${IVA_PCT}</td>
    </tr>`;
  };

  return `<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><title>Borrador OT${num} - ferrosCA</title>
<style>
  @page { size: A4; margin: 10mm 12mm; }
  * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; color-adjust: exact; }
  body { font-family: Arial, Helvetica, sans-serif; color: #1f2937; font-size: 10.5px; margin: 0; }
  .cabecera img { width: 100%; display: block; }
  .bloques { display: flex; gap: 14px; margin-top: 10px; }
  .col-izq { width: 170px; flex-shrink: 0; }
  .col-fecha { width: 170px; flex-shrink: 0; }
  .col-cli { flex: 1; }
  .titulo-gris { background: #595959; color: #fff; font-weight: 700; text-align: center; padding: 4px 6px; font-size: 10px; }
  .caja { background: #ededed; padding: 4px 8px; min-height: 18px; }
  .centro { text-align: center; }
  .mt { margin-top: 10px; }
  .izq { display: flex; flex-direction: column; justify-content: space-between; width: 354px; flex-shrink: 0; }
  .fila { display: flex; gap: 14px; }
  .obra { font-weight: 700; margin-top: 10px; }
  table.lineas { width: 100%; border-collapse: separate; border-spacing: 2px; margin-top: 8px; }
  table.lineas th { background: #595959; color: #fff; font-size: 9.5px; padding: 4px 6px; text-align: center; }
  table.lineas td { padding: 3px 6px; vertical-align: top; background: #ededed; }
  table.lineas td.num { text-align: right; }
  table.lineas td.uni { text-align: left; }
  .pie { display: flex; gap: 90px; margin-top: 16px; page-break-inside: avoid; }
  .pago { width: 330px; flex-shrink: 0; }
  .pago .titulo-gris { text-align: left; }
  .pago .cuerpo { background: #ededed; padding: 6px 8px; line-height: 1.6; }
  table.tot { flex: 1; border-collapse: separate; border-spacing: 2px 0; height: fit-content; }
  table.tot th { background: #595959; color: #fff; font-size: 9.5px; padding: 4px 6px; }
  table.tot td { padding: 4px 8px; text-align: right; background: #ededed; }
  table.tot tr.final td { font-weight: 700; }
  .lopd { font-family: "Times New Roman", serif; font-size: 7.5px; line-height: 1.25; margin-top: 18px; text-align: justify; page-break-inside: avoid; }
  .banner { margin-top: 18px; page-break-inside: avoid; }
  .banner img { width: 100%; display: block; }
  @media print { .no-print { display: none; } }
  .no-print { position: fixed; top: 8px; right: 8px; background: #595959; color: #fff; border: 0; border-radius: 6px; padding: 8px 14px; font-weight: 700; cursor: pointer; }
</style></head><body>
  <button class="no-print" onclick="window.print()">Imprimir / Guardar PDF</button>
  <div class="cabecera"><img src="${CABECERA_FERROS}" alt="ferrosCA - FERROS COLL DE L'ALBA S.L."></div>

  <div class="bloques">
    <div class="izq">
      <div class="fila">
        <div class="col-izq">
          <div class="titulo-gris">BORRADOR FACTURA</div>
          <div class="caja centro">BORRADOR OT${num}</div>
          <div class="titulo-gris mt">C.I.F CLIENTE</div>
          <div class="caja centro">${escapa(cifCliente || "")}</div>
        </div>
        <div class="col-fecha">
          <div class="titulo-gris">FECHA BORRADOR</div>
          <div class="caja centro">${fechaLarga(hoy)}</div>
        </div>
      </div>
      <div class="caja obra">Nº Obra:&nbsp;&nbsp;OT ${num}</div>
    </div>
    <div class="col-cli">
      <div class="titulo-gris">INFORMACIÓN CLIENTE</div>
      <div class="caja" style="min-height:130px">${escapa(cliente || "")}</div>
    </div>
  </div>

  <table class="lineas">
    <thead><tr>
      <th style="width:100px">COD. ARTÍCULO</th>
      <th>DESCRIPCIÓN</th>
      <th style="width:70px">CANTIDAD</th>
      <th style="width:62px">UNIDAD</th>
      <th style="width:52px">PRECIO</th>
      <th style="width:44px">DTO</th>
      <th style="width:62px">IMPORTE</th>
      <th style="width:34px">IVA</th>
    </tr></thead>
    <tbody>
      ${filas.map(filaHtml).join("\n")}
    </tbody>
  </table>

  <div class="pie">
    <div class="pago">
      <div class="titulo-gris">FORMA DE PAGO</div>
      <div class="cuerpo">
        Transferencia bancaria CaixaBank<br>
        ES4121000019490200713350 &nbsp;&nbsp;&nbsp;<b>SWIFT:</b> CAIXESBBXXX<br>
        <b>Vtos.:</b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;${fechaLarga(vto)}<br>
        <b>Importes:</b>&nbsp;&nbsp;${eurN(total)} €
      </div>
    </div>
    <table class="tot">
      <thead><tr><th>BASE IMPONIBLE</th><th>%</th><th>IVA</th><th>TOTAL</th></tr></thead>
      <tbody>
        <tr><td>${eurN(base)}</td><td style="text-align:center">${IVA_PCT}</td><td>${eurN(iva)}</td><td></td></tr>
        <tr class="final"><td>${eurN(base)}</td><td></td><td></td><td>${eurN(total)}</td></tr>
      </tbody>
    </table>
  </div>

  <div class="lopd">${LOPD}</div>

  <div class="banner"><img src="${BANNER_FERROS}" alt="ferrosCA"></div>
</body></html>`;
}
